"""Original Russian exercises. MOOC URLs are topic references, not adapted text/tests."""
DATA_PYTHON=[]
def add(title,theory,example,walk,task,starter,cases,solution,alternative,part,error):
 ident=f'py-data-{len(DATA_PYTHON)+1:02d}'
 DATA_PYTHON.append(dict(id=ident,track='python-data',module='Python для первых данных',level='Начальный',curriculumLevel=1,
  title=title,intro='Практика Python на небольших наборах наблюдений.',theory=[theory,'Все вычисления выполняются локально в поддерживаемом учебном поднаборе Python.'],
  example=example,task=task,starter=starter,cases=[{'stdin':list(map(str,stdin)),'stdout':stdout} for stdin,stdout in cases],solution=solution,alternative_solutions=[alternative],
  hints=[walk,error],source_url=f'https://programming-26.mooc.fi/part-{part}/',source_note='↗ Темы внешнего курса; упражнение CodeMentor оригинальное',
  prerequisites=[DATA_PYTHON[-1]['id']] if DATA_PYTHON else [],
  learning={'walkthrough':walk,'first':'Измени один вход примера и предскажи ответ до запуска.','medium':'Проверь случай с нулём и объясни результат.','independent':task,'errors':error,'review':'Вспомни: input() возвращает строку; числовой ввод преобразуем через int().','checkpoint':'Пройди все тесты. Объясни результат хотя бы одного граничного примера.'}))
add('Читаемый отчёт', 'print() принимает несколько значений и разделяет их пробелами. input() читает строку; int() превращает запись целого числа в число.',
 'day = input()\namount = int(input())\nprint("Запись:", day, amount)',
 'Прочитай день строкой, расход целым числом. Слова и числа в print разделяй запятыми: пробел добавится автоматически.',
 'Вводятся день (непустая строка без пробелов) и целый неотрицательный расход. Выведи две строки: «День: <день>» и «Расход: <число>». Угловые скобки не выводи.',
 'day = input()\namount = int(input())\n# Выведи две строки отчёта\n',
 [(['1',120],'День: 1\nРасход: 120'),(['02',0],'День: 02\nРасход: 0'),(['Среда',80],'День: Среда\nРасход: 80'),(['31',1000000],'День: 31\nРасход: 1000000')],
 'day = input()\namount = int(input())\nprint("День:", day)\nprint("Расход:", amount)',
 'print("День:", input())\nprint("Расход:", int(input()))',1,'Не добавляй приглашения к input(): проверяется только оговорённый вывод. День остаётся строкой, поэтому 02 не превращается в 2.')
add('Сумма двух расходов','После int() расходы можно складывать. Ввод и вычисление лучше разделять: так проще найти ошибку.',
 'a = int(input())\nb = int(input())\ntotal = a + b\nprint(total)',
 'Прочитай оба значения. Сложи их, затем выведи только сумму.',
 'Вводятся два целых неотрицательных расхода, каждый не больше 1000000. Выведи общую сумму одним числом.',
 'a = int(input())\nb = int(input())\n# Найди и выведи сумму\n',
 [([120,80],'200'),([0,0],'0'),([0,75],'75'),([1000000,1000000],'2000000')],
 'a = int(input())\nb = int(input())\nprint(a + b)',
 'print(int(input()) + int(input()))',1,'Без int() оператор + склеит строки: "12"+"3" даст "123", а не 15.')
add('Проверка лимита','Условие выбирает одну ветку. Если расход ровно равен лимиту, превышения нет: используем <=.',
 'amount = 80\nlimit = 100\nif amount <= limit:\n    print("Можно")\nelse:\n    print("Лимит")',
 'Сравни расход с лимитом. Равенство относится к первой ветке.',
 'Вводятся целые неотрицательные расход и лимит. Выведи «В пределах», если расход не больше лимита, иначе «Превышение».',
 'amount = int(input())\nlimit = int(input())\n# Добавь условие и вывод\n',
 [([80,100],'В пределах'),([100,100],'В пределах'),([101,100],'Превышение'),([0,0],'В пределах')],
 'amount = int(input())\nlimit = int(input())\nif amount <= limit:\n    print("В пределах")\nelse:\n    print("Превышение")',
 'amount = int(input())\nlimit = int(input())\nif amount > limit:\n    print("Превышение")\nelse:\n    print("В пределах")',2,'Проверь именно равенство: amount < limit ошибочно отвергнет расход, равный лимиту.')
add('Сумма списка наблюдений','Накопитель начинается с нуля. range(n) повторяет чтение ровно n раз. Если n=0, цикл не выполнится и сумма останется нулевой.',
 'total = 0\nfor i in range(3):\n    value = int(input())\n    total += value\nprint(total)',
 'Прочитай n до цикла. Создай total=0. Внутри прибавляй очередное значение, а итог выводи после цикла.',
 'Вводится n от 0 до 100, затем n целых неотрицательных расходов. Выведи их сумму. При n=0 выведи 0.',
 'n = int(input())\ntotal = 0\n# Прочитай n значений и накопи сумму\nprint(total)',
 [([3,10,20,30],'60'),([0],'0'),([1,7],'7'),([4,0,5,0,2],'7')],
 'n = int(input())\ntotal = 0\nfor i in range(n):\n    total += int(input())\nprint(total)',
 'n = int(input())\ns = 0\ni = 0\nwhile i < n:\n    s += int(input())\n    i += 1\nprint(s)',3,'Не обнуляй total внутри цикла. print(total) должен быть после цикла, иначе появятся лишние строки.')
add('Частота положительных значений','Счётчик увеличивается на 1, когда очередное наблюдение удовлетворяет условию. Сумма значений и количество подходящих наблюдений — разные показатели.',
 'count = 0\nfor value in [-1, 2, 0, 5]:\n    if value > 0:\n        count += 1\nprint(count)',
 'Для каждого числа проверь value>0. При успехе добавляй к счётчику единицу, а не само число.',
 'Вводится n от 0 до 100, затем n целых чисел. Выведи количество строго положительных. Ноль не считается положительным.',
 'n = int(input())\ncount = 0\n# Проверь каждое наблюдение\nprint(count)',
 [([4,-1,2,0,5],'2'),([0],'0'),([3,0,0,0],'0'),([4,-3,-2,-1,1],'1')],
 'n = int(input())\ncount = 0\nfor i in range(n):\n    value = int(input())\n    if value > 0:\n        count += 1\nprint(count)',
 'n = int(input())\ncount = 0\ni = 0\nwhile i < n:\n    value = int(input())\n    if value >= 1:\n        count += 1\n    i += 1\nprint(count)',3,'Условие >=0 ошибочно засчитает нули. Выводится частота, а не сумма положительных чисел.')
add('Функция для размаха','Размах — максимум минус минимум. Функция может возвращать число через return, а вывод выполняется снаружи. Решение проверяется по поведению, допустим и другой корректный способ.',
 'def spread(a, b):\n    return max(a, b) - min(a, b)\nprint(spread(-2, 5))',
 'Функция принимает три значения. Найди максимум и минимум, верни их разность. Прочитай вход и выведи результат вызова.',
 'Вводятся три целых наблюдения от −1000000 до 1000000. Выведи размах. Рекомендуется выделить вычисление в функцию; иной правильный алгоритм тоже принимается.',
 'def spread(a, b, c):\n    return 0\n\na = int(input())\nb = int(input())\nc = int(input())\nprint(spread(a, b, c))',
 [([1,4,7],'6'),([-2,1,5],'7'),([3,3,3],'0'),([-1000000,0,1000000],'2000000')],
 'def spread(a, b, c):\n    return max(a, b, c) - min(a, b, c)\na = int(input())\nb = int(input())\nc = int(input())\nprint(spread(a, b, c))',
 'values = [int(input()), int(input()), int(input())]\nprint(max(values) - min(values))',4,'Размах не зависит от порядка ввода. Вычитание последнего числа из первого не заменяет поиск максимума и минимума.')
